import test from 'node:test';
import assert from 'node:assert/strict';
import * as sim from '../src/simulation.js';
// Published 23b99bee engine, source blob 34535eb126ece2bfeb4f403abe50abe2fb316bb7.
// Only its board import path differs. Old saves below are generated by this
// actual engine, never by removing a version field from a current run.
import * as prior from './fixtures/pre-aftermath-simulation.js';
import { restoreSave } from '../src/save.js';

const copy = value => structuredClone(value);
const reload = state => restoreSave(JSON.parse(JSON.stringify({ state }))).state;
const at = (state, id) => state.cells.find(cell => cell.id === id);
const mutuals = state => state.institutions.filter(i => i.kind === 'mutual');
const source = { politics: .1, economy: .6, science: .1, religion: .55 };

function choose(api, state, actorId, cellId, actionId) {
  const action = api.getActions(state, cellId, actorId).find(a => a.id === actionId);
  assert.ok(action, `${actorId} can choose ${actionId} at ${cellId}, year ${state.year}`);
  for (const id of action.requireEvidence) {
    if (!api.getInvestigation(state, actorId, cellId).evidence.includes(id)) {
      api.investigate(state, actorId, cellId, id);
    }
  }
  api.lockTask(state, actorId, cellId, actionId);
}
function arrange(api, state, tasks = []) {
  for (const task of tasks) if (!state.drafts[task[0]]) choose(api, state, ...task);
}
function submit(api, state) {
  for (const actor of api.getActors(state)) if (!state.drafts[actor.id]) api.passTask(state, actor.id);
  api.commitWindow(state);
}
function decade(api, state, tasks = []) {
  arrange(api, state, tasks);
  submit(api, state);
  api.advanceToNextWindow(state);
  return state;
}
function finish(api, state, script) {
  while (state.year < 40) {
    if (state.phase === 'planning') {
      arrange(api, state, script[state.year]);
      submit(api, state);
    }
    api.advanceToNextWindow(state);
  }
  return state;
}
function recruited({ recruitment = 'recruit_successor', build, seed = 0 } = {}, api = sim) {
  const state = api.createRun(seed);
  decade(api, state, build ? [['protagonist', 'D4', build]] : []);
  decade(api, state, [['protagonist', 'D4', recruitment]]);
  assert.equal(state.year, 20);
  assert.ok(api.getActors(state).some(actor => actor.id === 'linche'));
  return state;
}
function beforeAid20({ early = false } = {}) {
  const state = sim.createRun(0);
  decade(sim, state);
  decade(sim, state, early ? [['protagonist', 'D5', 'mutual_aid']] : []);
  return state;
}
function window30(kind = 'disaster') {
  const state = sim.createRun(0);
  decade(sim, state, kind === 'averted' ? [['protagonist', 'B4', 'preserve_records']] : []);
  decade(sim, state, kind === 'averted' ? [['protagonist', 'E4', 'fund_school']] : []);
  decade(sim, state, kind === 'averted' ? [['protagonist', 'B4', 'independent_review']]
    : kind === 'contained' ? [['protagonist', 'B4', 'local_veto']] : []);
  assert.equal(state.flags.crisis.status, kind);
  return state;
}

test('new runs persist and validate their separate aftermath contract', () => {
  const state = sim.createRun(0);
  assert.equal(state.aftermathRulesVersion, sim.AFTERMATH_RULES.version);
  assert.equal(sim.usesAftermathRules(state), true);
  assert.deepEqual(reload(state), state);
  const bad = copy(state);
  bad.aftermathRulesVersion = 'aftermath-unknown';
  assert.equal(sim.validateState(bad).valid, false);
  assert.throws(() => reload(bad), /角色与后续互助规则版本非法/);
});

for (const recruitment of ['recruit_successor', 'recruit_risk']) {
  for (const { build, seed, label } of [
    { seed: 0, label: 'no build' },
    { build: 'build_joint', seed: 0, label: 'successful build' },
    { build: 'build_joint', seed: 6, label: 'failed build' },
  ]) {
    test(`${recruitment}, ${label}: Linche refuses only personal forced relocation`, () => {
      const state = recruited({ recruitment, build, seed });
      if (build) assert.equal(state.events.find(e => e.actionId === build).status, label === 'failed build' ? 'failed' : 'success');
      const original = copy(state);
      const refusals = sim.getActorRefusals(state, 'linche', 'D4');
      assert.equal(refusals.length, 1);
      assert.equal(refusals[0].actionId, 'relocate_teacher');
      const event = state.events.find(e => e.actionId === recruitment);
      assert.equal(refusals[0].sourceEventId, event.id);
      assert.match(refusals[0].reason, recruitment === 'recruit_successor' ? /苏岚同意接班|自己签名/ : /没有安排继任|岗位缺口/);
      assert.ok(sim.getActions(state, 'D4', 'protagonist').some(a => a.id === 'relocate_teacher'));
      assert.deepEqual(sim.getActions(state, 'D4', 'linche').map(a => a.id), ['free_warning', 'present_archive']);
      for (const cellId of ['B4', 'F6', 'D5', 'E4']) {
        assert.ok(sim.getActions(state, cellId, 'linche').length, `${cellId} remains available`);
        assert.deepEqual(sim.getActorRefusals(state, 'linche', cellId), []);
      }
      assert.deepEqual(sim.getActorRefusals(state, 'protagonist', 'D4'), []);
      assert.deepEqual(state, original, 'reading a refusal spends no budget or action');
    });
  }
}

test('refusal rationale follows the successful recruitment event rather than mutable staffing flags', () => {
  for (const recruitment of ['recruit_successor', 'recruit_risk']) {
    const state = recruited({ recruitment });
    const refusal = sim.getActorRefusals(state, 'linche', 'D4');
    state.flags.successor = !state.flags.successor;
    assert.deepEqual(sim.getActorRefusals(state, 'linche', 'D4'), refusal);
    state.events.find(e => e.actionId === recruitment).status = 'failed';
    const missing = sim.getActorRefusals(state, 'linche', 'D4')[0];
    assert.equal(missing.sourceEventId, null);
    assert.match(missing.reason, /缺少可核实/);
    assert.doesNotMatch(missing.reason, /第11年/);
  }
});

test('refusing a direct lock preserves other drafts, spent investigations and all costs', () => {
  const state = recruited();
  choose(sim, state, 'protagonist', 'B4', 'independent_review');
  choose(sim, state, 'linche', 'D4', 'present_archive');
  const original = copy(state);
  assert.throws(() => sim.lockTask(state, 'linche', 'D4', 'relocate_teacher'), /自己签名|调令/);
  assert.deepEqual(state, original);
  assert.equal(sim.getWindowReview(state).ready, true);
  submit(sim, state);
  sim.advanceToNextWindow(state);
  assert.equal(state.flags.respected, true);
  assert.notEqual(state.flags.forced, true);
});

test('forged refused drafts are rejected atomically by review, submission and import', () => {
  const state = recruited({ recruitment: 'recruit_risk' });
  choose(sim, state, 'protagonist', 'B4', 'local_veto');
  state.drafts.linche = { actorId: 'linche', cellId: 'D4', actionId: 'relocate_teacher', evidence: [], status: 'locked', window: 20 };
  const original = copy(state);
  const review = sim.getWindowReview(state);
  assert.equal(review.ready, false);
  assert.match(review.issues.join(' '), /岗位缺口|调令/);
  assert.throws(() => sim.commitWindow(state), /岗位缺口|调令/);
  assert.equal(sim.validateState(state).valid, false);
  assert.throws(() => reload(state), /拒绝执行的迁任/);
  assert.deepEqual(state, original);
});

test('forged Linche relocation events fail validation before any yearly changes', () => {
  const state = recruited();
  choose(sim, state, 'linche', 'D4', 'present_archive');
  submit(sim, state);
  const event = state.events.find(e => e.actionId === 'present_archive');
  event.actionId = 'relocate_teacher';
  const original = copy(state);
  assert.equal(sim.validateState(state).valid, false);
  assert.throws(() => sim.advanceYear(state), /迁任不能成为事件合同/);
  assert.throws(() => reload(state), /迁任不能成为事件合同/);
  assert.deepEqual(state, original);
});

test('the protagonist can still force relocation while Linche acts elsewhere', () => {
  const state = recruited({ build: 'build_joint' });
  choose(sim, state, 'protagonist', 'D4', 'relocate_teacher');
  choose(sim, state, 'linche', 'B4', 'local_veto');
  decade(sim, state);
  assert.equal(state.flags.forced, true);
  assert.equal(state.flags.trust, false);
  assert.ok(state.institutions.some(i => i.kind === 'school' && i.sourceActionId.includes(':protagonist:')));
  assert.ok(state.institutions.filter(i => i.cellId === 'D4').every(i => !i.active));
  assert.equal(sim.validateState(state).valid, true);
  assert.deepEqual(sim.getActorRefusals(state, 'linche', 'D4'), []);
});

test('first aid and expansion retain the paid carrier and exactly one D5 protection', () => {
  const first = beforeAid20();
  const one = beforeAid20({ early: true });
  const two = copy(one);
  for (const [state, mode] of [[first, 'first'], [two, 'expand']]) {
    const plan = sim.getAidPlan(state);
    assert.equal(plan.mode, mode);
    assert.equal(plan.later, false);
    const aid = sim.getActions(state, 'D5').find(a => a.id === 'mutual_aid');
    assert.deepEqual(aid.cost, { economy: 3 });
    assert.equal(aid.dueIn, 1);
    assert.equal(aid.probability, 1);
    assert.match(aid.modelNote, /仅对南岸D5|只为南岸D5/);
    choose(sim, state, 'protagonist', 'D5', 'mutual_aid');
    submit(sim, state);
  }
  submit(sim, one);
  sim.advanceYear(one);
  sim.advanceYear(two);
  assert.equal(mutuals(two).length, 2);
  assert.equal(mutuals(one).length, 1);
  for (const institution of mutuals(two)) assert.deepEqual(institution.annualSource, source);
  // Both branches start with identical cells before the extra action. At21,
  // the extra source is real production; economy also bears its decayed cost.
  for (const channel of ['politics', 'science', 'religion']) {
    assert.ok(Math.abs(at(two, 'D5').channels[channel] - at(one, 'D5').channels[channel] - source[channel]) < .00001);
  }
  assert.ok(Math.abs(at(two, 'D5').channels.economy - at(one, 'D5').channels.economy - (-3 * .94 + .6)) < .00001);
  sim.advanceToNextWindow(first);
  sim.advanceToNextWindow(one);
  sim.advanceToNextWindow(two);
  for (const state of [first, one, two]) {
    assert.deepEqual(state.flags.crisis.damageByCell, { D4: 1, E4: 1, D5: .7, F6: 1 });
    assert.equal(state.flags.crisis.damage, .925);
  }
  assert.deepEqual(two.flags.crisis, one.flags.crisis);
  assert.equal(sim.getAidPlan(two).mode, 'expand');
});

for (const stoppedBy of ['inactive', 'unmaintained']) {
  test(`${stoppedBy} aid shows restart, retains the old carrier and starts a new one only on resolution`, () => {
    const state = beforeAid20({ early: true });
    const old = mutuals(state)[0];
    // Isolate the pre-existing carrier state; no player-facing closure action
    // is invented to manufacture this maintenance boundary.
    if (stoppedBy === 'inactive') old.active = false;
    else old.maintenance = 0;
    const oldRecord = copy(old);
    assert.equal(sim.getAidPlan(state).mode, 'restart');
    assert.match(sim.getAidPlan(state).title, /重启/);
    choose(sim, state, 'protagonist', 'D5', 'mutual_aid');
    assert.equal(mutuals(state).length, 1);
    submit(sim, state);
    assert.equal(mutuals(state).length, 1);
    sim.advanceYear(state);
    assert.equal(mutuals(state).length, 2);
    assert.deepEqual(mutuals(state)[0], oldRecord);
    assert.equal(mutuals(state)[1].startYear, 21);
    assert.match(mutuals(state)[1].name, /重启/);
    assert.deepEqual(mutuals(state)[1].annualSource, source);
  });
}

test('new zero-maintenance aid supplies neither production nor year23 protection', () => {
  const state = beforeAid20({ early: true });
  const institution = mutuals(state)[0];
  institution.maintenance = 0;
  assert.equal(institution.active, true, 'maintenance is independent of the active flag');
  assert.equal(sim.getAidPlan(state).mode, 'restart');
  assert.equal(sim.validateState(state).valid, true);
  const originalCarrier = copy(institution);
  const noCarrierOutput = copy(state);
  mutuals(noCarrierOutput)[0].active = false;
  submit(sim, state);
  submit(sim, noCarrierOutput);
  sim.advanceYear(state);
  sim.advanceYear(noCarrierOutput);
  assert.deepEqual(state.cells, noCarrierOutput.cells, 'zero maintenance contributes no annual source');
  sim.advanceToNextWindow(state);
  assert.deepEqual(state.flags.crisis.damageByCell, { D4: 1, E4: 1, D5: 1, F6: 1 });
  assert.equal(state.flags.crisis.damage, 1);
  assert.deepEqual(mutuals(state)[0], originalCarrier, 'the nonworking carrier and its history remain');
  assert.deepEqual(reload(state), state);
});

test('genuine prior zero-maintenance aid retains its original active-only protection and full continuation', () => {
  const old = prior.createRun(0);
  decade(prior, old);
  decade(prior, old, [['protagonist', 'D5', 'mutual_aid']]);
  // Use the published engine to create the carrier and save. Only isolate
  // maintenance at this boundary; do not manufacture legacy by deleting a marker.
  mutuals(old)[0].maintenance = 0;
  assert.equal(Object.hasOwn(old, 'aftermathRulesVersion'), false);
  assert.equal(prior.validateState(old).valid, true);
  const expected = copy(old);
  const loaded = reload(old);
  assert.deepEqual(loaded, expected);
  assert.equal(sim.usesAftermathRules(loaded), false);
  decade(prior, expected);
  decade(sim, loaded);
  assert.equal(expected.flags.crisis.damageByCell.D5, .7);
  assert.equal(loaded.flags.crisis.damageByCell.D5, .7);
  assert.deepEqual(loaded, expected);
  const script = { 30: [['protagonist', 'D5', 'mutual_aid']] };
  finish(prior, expected, script);
  finish(sim, loaded, script);
  assert.deepEqual(loaded, expected, 'the later aid contract and complete ending history also remain unchanged');
  assert.deepEqual(sim.getEnding(loaded), prior.getEnding(expected));
  assert.deepEqual(reload(loaded), loaded);
});

for (const kind of ['averted', 'contained', 'disaster']) {
  test(`late aid after ${kind} promises current support without rewriting the recorded crisis`, () => {
    const state = window30(kind);
    const originalCrisis = copy(state.flags.crisis);
    const originalImpact = copy(state.history.find(e => e.id === 'crisis-impact'));
    const originalSnapshots = copy(state.snapshots);
    const originalHistory = copy(state.history);
    const readiness = sim.getHandoffReadiness(state);
    const plan = sim.getAidPlan(state);
    assert.equal(plan.later, true);
    assert.match(plan.title, /后续生计/);
    assert.match(plan.reward, /第31年起.*不会降低第23年/);
    assert.match(plan.risk, kind === 'averted' ? /损失已避免/ : /已有损失/);
    assert.doesNotMatch(plan.title + plan.description, /灾后重建/);
    assert.match(plan.modelNote, /不承诺尚未模拟的下一次灾害/);
    choose(sim, state, 'protagonist', 'D5', 'mutual_aid');
    assert.equal(mutuals(state).length, 0);
    const locked = reload(state);
    assert.deepEqual(locked, state);
    decade(sim, state);
    decade(sim, locked);
    assert.deepEqual(locked, state);
    assert.deepEqual(state.flags.crisis, originalCrisis);
    assert.deepEqual(state.history.find(e => e.id === 'crisis-impact'), originalImpact);
    assert.deepEqual(state.history.slice(0, originalHistory.length), originalHistory);
    for (const [year, snapshot] of Object.entries(originalSnapshots)) assert.deepEqual(state.snapshots[year], snapshot);
    assert.deepEqual(sim.getHandoffReadiness(state), readiness, 'mutual aid supplies no teaching, checking or consent points');
    assert.equal(mutuals(state)[0].startYear, 31);
    assert.deepEqual(mutuals(state)[0].annualSource, source);
    assert.match(state.history.find(e => e.id === 'resolved:event:action:30:protagonist:D5:mutual_aid').text, /不降低第23年/);
    assert.deepEqual(reload(state), state);
  });
}

test('missing historical crisis detail remains missing in late aid and its later outcome', () => {
  const state = window30();
  delete state.flags.crisis.damage;
  delete state.flags.crisis.damageByCell;
  const missing = copy(state.flags.crisis);
  const plan = sim.getAidPlan(state);
  assert.match(plan.risk, /缺少明细.*不补造损失/);
  assert.doesNotMatch(plan.risk, /损失已避免|已有损失/);
  decade(sim, state, [['protagonist', 'D5', 'mutual_aid']]);
  assert.deepEqual(state.flags.crisis, missing);
  assert.equal(Object.hasOwn(state.flags.crisis, 'damage'), false);
  assert.equal(Object.hasOwn(state.flags.crisis, 'damageByCell'), false);
});

test('repeated aid cannot turn an unprepared withdrawal into a positive handoff', () => {
  const state = recruited({ recruitment: 'recruit_risk' });
  decade(sim, state, [['linche', 'D5', 'mutual_aid']]);
  const before = sim.getHandoffReadiness(state);
  decade(sim, state, [['protagonist', 'D4', 'withdraw'], ['linche', 'D5', 'mutual_aid']]);
  assert.equal(mutuals(state).length, 2);
  assert.deepEqual(sim.getHandoffReadiness(state), before);
  assert.equal(sim.getEnding(state).title, '交班后的空椅子');
  assert.equal(sim.getEnding(state).metrics.delegatedStaff, 0);
  assert.equal(sim.getEnding(state).metrics.independentChecks, 0);
});

const oldRoutes = [
  {
    name: 'successor Linche relocation then first late aid', target: 20,
    script: {
      0: [['protagonist', 'D4', 'build_joint']],
      10: [['protagonist', 'D4', 'recruit_successor']],
      20: [['protagonist', 'B4', 'independent_review'], ['linche', 'D4', 'relocate_teacher']],
      30: [['protagonist', 'D4', 'share_power'], ['linche', 'D5', 'mutual_aid']],
    },
  },
  {
    name: 'risky Linche relocation without a built station', target: 20,
    script: {
      10: [['protagonist', 'D4', 'recruit_risk']],
      20: [['protagonist', 'B4', 'local_veto'], ['linche', 'D4', 'relocate_teacher']],
      30: [['protagonist', 'D4', 'withdraw'], ['linche', 'D5', 'mutual_aid']],
    },
  },
  {
    name: 'repeated early and late aid with unsuccessful handoff', target: 30,
    script: {
      10: [['protagonist', 'D4', 'recruit_risk']],
      20: [['protagonist', 'B4', 'local_veto'], ['linche', 'D5', 'mutual_aid']],
      30: [['protagonist', 'D4', 'withdraw'], ['linche', 'D5', 'mutual_aid']],
    },
  },
  {
    name: 'first late aid with a prepared and consenting shared handoff', target: 30,
    script: {
      0: [['protagonist', 'B4', 'preserve_records']],
      10: [['protagonist', 'D4', 'recruit_successor']],
      20: [['protagonist', 'D4', 'present_archive'], ['linche', 'E4', 'train_network']],
      30: [['protagonist', 'D4', 'share_power'], ['linche', 'D5', 'mutual_aid']],
    },
    ending: '许多人签署的历史',
  },
  {
    name: 'first late aid with prepared withdrawal after averted crisis', target: 30,
    script: {
      0: [['protagonist', 'D4', 'build_joint']],
      10: [['protagonist', 'D4', 'recruit_successor']],
      20: [['protagonist', 'B4', 'independent_review'], ['linche', 'E4', 'train_network']],
      30: [['protagonist', 'D4', 'withdraw'], ['linche', 'D5', 'mutual_aid']],
    },
    ending: '没有唯一守夜人',
  },
];

for (const route of oldRoutes) for (const stage of ['planning', 'locked', 'submitted', 'resolved', 'ended']) {
  test(`genuine prior save: ${route.name}, ${stage}, keeps its full continuation`, () => {
    const old = prior.createRun(0);
    assert.equal(Object.hasOwn(old, 'aftermathRulesVersion'), false);
    while (old.year < route.target) decade(prior, old, route.script[old.year]);
    if (stage !== 'planning') arrange(prior, old, route.script[old.year]);
    if (['submitted', 'resolved', 'ended'].includes(stage)) submit(prior, old);
    if (['resolved', 'ended'].includes(stage)) prior.advanceYear(old);
    if (stage === 'ended') finish(prior, old, route.script);
    const preserved = copy(old);
    const loaded = reload(old);
    assert.deepEqual(loaded, preserved, 'loading does not migrate an old contract');
    assert.equal(sim.usesAftermathRules(loaded), false);
    assert.deepEqual(sim.getActorRefusals(loaded, 'linche', 'D4'), []);
    if (loaded.phase === 'planning' && loaded.year === 20) {
      assert.ok(sim.getActions(loaded, 'D4', 'linche').some(a => a.id === 'relocate_teacher'));
    }
    if (loaded.phase === 'planning' && loaded.year === 30) {
      const oldAid = prior.getActions(preserved, 'D5', 'linche').find(a => a.id === 'mutual_aid');
      const aid = sim.getActions(loaded, 'D5', 'linche').find(a => a.id === 'mutual_aid');
      for (const key of ['id', 'title', 'description', 'cost', 'probability', 'dueIn', 'requireEvidence']) {
        assert.deepEqual(aid[key], oldAid[key], `${key} preserves the old stored contract`);
      }
      assert.match(aid.reward, /不降低过去的损失/);
      assert.match(aid.modelNote, /不追溯改变第23年/);
      assert.deepEqual(loaded, preserved, 'read-only clarification does not modify the save');
    }
    const expected = finish(prior, preserved, route.script);
    finish(sim, loaded, route.script);
    assert.equal(sim.validateState(loaded).valid, true);
    assert.deepEqual(loaded, expected, 'cells, snapshots, contracts, sources and history all match');
    assert.deepEqual(sim.getEnding(loaded), prior.getEnding(expected));
    if (route.ending) assert.equal(sim.getEnding(loaded).title, route.ending);
    assert.deepEqual(reload(loaded), loaded);
  });
}
